import React, { useState } from 'react';
import { FiFilter, FiDownload, FiEye, FiPlus } from 'react-icons/fi';
import { HiOutlineSortAscending } from 'react-icons/hi';
import { FaThumbtack } from 'react-icons/fa';
import Navbar from '../../components/Navbar';
import '../../styles/tokens.css';

export default function DatasetExplorerPage() {
  const [filters, setFilters] = useState({});
  const [datasets, setDatasets] = useState(Array(7).fill({}));

  return (
    <>
      <Navbar />
      <div className="flex min-h-screen h-screen page-bg">
        {/* Sidebar */}
        <aside className="w-64 p-4 bg-card-light dark:bg-card-dark border-r border-default">
          <h2 className="text-lg font-semibold text-textPrimary-light dark:text-textPrimary-dark mb-4">Filters</h2>
          <input type="text" placeholder="Search datasets..." className="w-full mb-4 p-2 rounded border-default bg-card-light dark:bg-card-dark text-textPrimary-light dark:text-textPrimary-dark" />

          <div className="mb-4">
            <h3 className="font-medium text-textSecondary-light dark:text-textSecondary-dark">Geography</h3>
            {['North America', 'Europe', 'Asia', 'Africa', 'South America', 'Australia/Oceania'].map(region => (
              <label key={region} className="block text-sm text-textSecondary-light dark:text-textSecondary-dark">
                <input type="checkbox" className="mr-2" />{region}
              </label>
            ))}
          </div>

          <div className="mb-4">
            <h3 className="font-medium text-textSecondary-light dark:text-textSecondary-dark">Data Type</h3>
            {['Survey Data', 'Clinical Trials', 'Longitudinal Studies', 'Census Data', 'Administrative Data'].map(type => (
              <label key={type} className="block text-sm text-textSecondary-light dark:text-textSecondary-dark">
                <input type="checkbox" className="mr-2" />{type}
              </label>
            ))}
          </div>

          <div className="mb-4">
            <h3 className="font-medium text-textSecondary-light dark:text-textSecondary-dark">Date Range</h3>
            <input type="date" className="w-full mb-2 border-default p-1 rounded bg-card-light dark:bg-card-dark text-textPrimary-light dark:text-textPrimary-dark" />
            <input type="date" className="w-full border-default p-1 rounded bg-card-light dark:bg-card-dark text-textPrimary-light dark:text-textPrimary-dark" />
          </div>

          <div className="mb-4">
            <h3 className="font-medium text-textSecondary-light dark:text-textSecondary-dark">Demographics</h3>
            {['Children (0-12)', 'Adolescents (13-17)', 'Young Adults (18-25)', 'Adults (26-64)', 'Seniors (65+)'].map(demo => (
              <label key={demo} className="block text-sm text-textSecondary-light dark:text-textSecondary-dark">
                <input type="checkbox" className="mr-2" />{demo}
              </label>
            ))}
          </div>

          <button className="btn-accent w-full mt-2">Apply Filters</button>
          <button className="text-sm text-blue-600 mt-2 hover:underline">Reset All</button>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-6">
          {/* Header */}
          <div className="flex justify-between items-center mb-4">
            <h1 className="text-2xl font-bold text-gray-800 dark:text-white">Datasets</h1>
            <div className="flex gap-2">
              <button className="btn-outline flex items-center gap-1"><FiFilter /> Filter</button>
              <button className="btn-outline flex items-center gap-1"><HiOutlineSortAscending /> Sort</button>
              <button className="btn-accent">+ Request Dataset</button>
            </div>
          </div>

          {/* Metrics */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            {[
              ['Total Datasets', 128],
              ['Pinned Datasets', 7],
              ['Recently Updated', 23],
              ['Total Variables', '4,582'],
            ].map(([label, value]) => (
              <div
                key={label}
                className="p-4 rounded-lg bg-white dark:bg-gray-850 border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-200 shadow-sm"
              >
                <p className="text-sm">{label}</p>
                <span className="font-bold text-xl">{value}</span>
              </div>
            ))}
          </div>

          {/* Dataset Table */}
          <div className="bg-white dark:bg-gray-850 border border-gray-300 dark:border-gray-700 rounded-lg shadow-md">
            <div className="p-4 border-b border-gray-200 dark:border-gray-700 font-semibold text-gray-700 dark:text-gray-200">Name</div>
            {datasets.map((_, index) => (
              <div
                key={index}
                className="grid grid-cols-6 items-center gap-4 p-4 border-b border-gray-200 dark:border-gray-700 text-sm hover:bg-gray-100 dark:hover:bg-gray-800 transition-all"
              >
                <div className="col-span-2">
                  <div className="flex items-center gap-2">
                    <FaThumbtack className="text-yellow-500" />
                    <div>
                      <p className="font-semibold text-gray-800 dark:text-white">Example Dataset {index + 1}</p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">This is a short description</p>
                    </div>
                  </div>
                </div>
                <div className="text-gray-700 dark:text-gray-300">Source Org</div>
                <div className="text-gray-700 dark:text-gray-300">Jun 1, 2023</div>
                <div className="text-gray-700 dark:text-gray-300">247</div>
                <div className="flex gap-2 text-gray-600 dark:text-gray-300">
                  <FiPlus className="cursor-pointer hover:text-blue-500" />
                  <FiEye className="cursor-pointer hover:text-blue-500" />
                  <FiDownload className="cursor-pointer hover:text-blue-500" />
                </div>
              </div>
            ))}
          </div>

          {/* Pagination */}
          <div className="flex justify-end mt-4 gap-1">
            {[1, 2, 3, 4, 5].map(page => (
              <button
                key={page}
                className="px-3 py-1 rounded border border-gray-300 dark:border-gray-700 text-sm bg-white dark:bg-gray-850 text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                {page}
              </button>
            ))}
          </div>
        </main>
      </div>
    </>
  );
}
